"use client";

import { FormEvent, useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { apiFetch } from "@/lib/api";
import { getStoredSession } from "@/lib/session";
import { Card } from "@/components/ui/card";

type Project = { id: string; name: string; customer?: string | null; status: string; budget?: string | number | null; tasks: { id: string }[] };
type Task = { id: string; title: string; status: string; priority: string; project?: { name: string } | null; dueDate?: string | null };

function useList<T>(path: string) { const [items, setItems] = useState<T[]>([]); const [error, setError] = useState(""); const reload = () => void apiFetch<{ items: T[] }>(path).then((data) => setItems(data.items)).catch((e) => setError(e instanceof Error ? e.message : "Unable to load data.")); useEffect(reload, [path]); return { items, error, reload }; }

export function LiveProjects() { const projects = useList<Project>("/projects"); const tasks = useList<Task>("/tasks"); const [name, setName] = useState(""); const save = async (event: FormEvent) => { event.preventDefault(); await apiFetch("/projects", { method: "POST", body: JSON.stringify({ name }) }); setName(""); projects.reload(); }; return <section className="space-y-5"><div><p className="text-sm font-semibold uppercase tracking-[0.16em] text-brand-500">Delivery workspace</p><h1 className="mt-2 text-3xl font-semibold text-ink">Projects and tasks</h1></div><Card className="p-5"><form onSubmit={save} className="flex gap-3"><input required value={name} onChange={(e) => setName(e.target.value)} placeholder="New project name" className="flex-1 rounded-xl border border-line px-3 py-2" /><button className="rounded-xl bg-brand-500 px-4 py-2 font-semibold text-white">Create project</button></form></Card><div className="grid gap-5 lg:grid-cols-2"><Card className="p-5"><h2 className="font-semibold">Projects</h2><div className="mt-4 space-y-3">{projects.items.map((item) => <div key={item.id} className="rounded-xl border border-line p-3"><div className="flex justify-between"><span className="font-semibold">{item.name}</span><span className="text-xs text-slate-500">{item.status}</span></div><p className="mt-1 text-xs text-slate-500">{item.tasks.length} tasks</p></div>)}</div></Card><Card className="p-5"><h2 className="font-semibold">Tasks</h2><div className="mt-4 space-y-3">{tasks.items.map((item) => <div key={item.id} className="rounded-xl border border-line p-3"><div className="flex justify-between"><span>{item.title}</span><span className="text-xs text-slate-500">{item.status}</span></div><p className="mt-1 text-xs text-slate-500">{item.project?.name ?? "Unassigned project"} · {item.priority}</p></div>)}</div></Card></div></section>; }

type Attendance = { id: string; date: string; status: string; checkInAt?: string | null; checkOutAt?: string | null };
export function LiveAttendance() { const searchParams = useSearchParams(); const qrToken = searchParams.get("employeeQr") || searchParams.get("qr"); const { items, error, reload } = useList<Attendance>("/attendance/history"); const [message, setMessage] = useState(""); const [qrDataUrl, setQrDataUrl] = useState(""); const getLocation = () => { if (!navigator.geolocation) return Promise.reject(new Error("Location permission is required to record attendance.")); return new Promise<string>((resolve, reject) => navigator.geolocation.getCurrentPosition((position) => resolve(`${position.coords.latitude.toFixed(6)}, ${position.coords.longitude.toFixed(6)}`), () => reject(new Error("Please enable location permission before clocking in or out.")), { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 })); }; const action = async (path: string) => { try { const location = await getLocation(); await apiFetch(path, { method: "POST", body: JSON.stringify({ method: qrToken ? "QR" : "WEB", employeeQrToken: qrToken || undefined, location }) }); setMessage(path.includes("in") ? "Clocked in successfully." : "Clocked out successfully."); reload(); } catch (e) { setMessage(e instanceof Error ? e.message : "Attendance action failed."); } }; const generateQr = async () => { try { const result = await apiFetch<{ qrDataUrl: string }>("/attendance/qr", { method: "POST" }); setQrDataUrl(result.qrDataUrl); setMessage("Organisation attendance QR generated."); } catch (e) { setMessage(e instanceof Error ? e.message : "Unable to generate attendance QR."); } }; return <section className="space-y-5"><div><p className="text-sm font-semibold uppercase tracking-[0.16em] text-brand-500">Employee time</p><h1 className="mt-2 text-3xl font-semibold text-ink">{qrToken ? "Employee clock-in" : "Attendance"}</h1><p className="mt-2 text-slate-600">{qrToken ? "Confirm the clock-in for the employee assigned to this QR code." : "Clock-in and clock-out actions use your assigned office geofence."}</p></div><Card className="p-6"><div className="flex flex-wrap gap-3"><button onClick={() => void action("/attendance/clock-in")} className="rounded-xl bg-brand-500 px-4 py-2 font-semibold text-white">Clock in{qrToken ? " employee" : ""}</button><button onClick={() => void action("/attendance/clock-out")} className="rounded-xl border border-line px-4 py-2 font-semibold">Clock out</button><button onClick={() => void generateQr()} className="rounded-xl border border-line px-4 py-2 font-semibold">Generate organisation QR</button></div>{qrDataUrl && <img src={qrDataUrl} alt="Organisation attendance QR code" className="mt-4 h-48 w-48 rounded-xl border border-line p-2" />}{message && <p className="mt-3 text-sm text-slate-600">{message}</p>}</Card>{error && <p className="text-sm text-rose-600">{error}</p>}<Card className="overflow-hidden"><table className="w-full text-left text-sm"><thead className="bg-soft"><tr><th className="p-4">Date</th><th className="p-4">Status</th><th className="p-4">Clock in</th><th className="p-4">Clock out</th></tr></thead><tbody>{items.map((item) => <tr key={item.id} className="border-t border-line"><td className="p-4">{new Date(item.date).toLocaleDateString()}</td><td className="p-4">{item.status}</td><td className="p-4">{item.checkInAt ? new Date(item.checkInAt).toLocaleTimeString() : "—"}</td><td className="p-4">{item.checkOutAt ? new Date(item.checkOutAt).toLocaleTimeString() : "—"}</td></tr>)}{items.length === 0 && <tr><td colSpan={4} className="p-8 text-center text-slate-500">No attendance records yet.</td></tr>}</tbody></table></Card></section>; }

type AttendanceReport = { summary: { scheduled: number; present: number; absent: number; late: number; missingClockOut: number; hours: number; overtime: number } };
export function LiveAttendanceReport() { const [report, setReport] = useState<AttendanceReport | null>(null); const [error, setError] = useState(""); useEffect(() => { void apiFetch<AttendanceReport>("/attendance/report").then(setReport).catch((reason) => setError(reason instanceof Error ? reason.message : "Unable to load attendance report.")); }, []); if (error) return <p className="text-sm text-slate-500">{error}</p>; if (!report) return <p className="text-sm text-slate-500">Loading attendance report…</p>; const cards = [["Scheduled", report.summary.scheduled], ["Present", report.summary.present], ["Absent", report.summary.absent], ["Late", report.summary.late], ["Missing clock-out", report.summary.missingClockOut], ["Hours", report.summary.hours], ["Overtime", report.summary.overtime]]; return <Card className="p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="font-semibold">Attendance report</h2><p className="mt-1 text-sm text-slate-500">Last 30 days based on active employee schedules.</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-xl bg-soft p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 text-xl font-semibold text-ink">{value}</p></div>)}</div></Card>; }
